-- CampBuddy — Gipfel für die Region CH.
-- Ausführen: Supabase-Projekt -> SQL Editor -> Inhalt einfügen -> Run.
-- Setzt Migration 0010 voraus.
--
-- 7274 benannte Gipfel mit Höhe aus OpenStreetMap (ODbL).
-- Reine Orientierung, keine Rechtsaussage.
-- Teil 1 von 2.

begin;
on conflict (id) do update set region = excluded.region, name = excluded.name, lat = excluded.lat, lng = excluded.lng, elevation = excluded.elevation, source_url = excluded.source_url, updated_at = now();
commit;
